<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad,onPullDownRefresh,onShow } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import SessionTrigger from '@/shared/components/SessionTrigger.vue'
import { distributionApi } from '@/features/distribution/api/distribution.api'
import type { DistributionFilterOption } from '@/features/distribution/models/distribution'
import { restockApi } from '../../api/restock.api'
import type { RestockDemand } from '../../models/restock'

const date=ref(new Date().toISOString().slice(0,10)),status=ref<'pending'|'completed'>('pending'),keyword=ref(''),type=ref(0),zone=ref(''),draftZone=ref(''),zones=ref<DistributionFilterOption[]>([]),list=ref<RestockDemand[]>([]),loading=ref(false),error=ref(''),zoneVisible=ref(false),expanded=ref(''),selected=ref<string[]>([])
const sessionPickerVisible=ref(false)
const visibleList=computed(()=>list.value.filter(item=>(status.value==='pending'?item.pendingNum>0:item.pendingNum===0)&&item.productName.includes(keyword.value.trim())))
const pendingKinds=computed(()=>list.value.filter(item=>item.pendingNum>0).length),completedKinds=computed(()=>list.value.filter(item=>item.pendingNum===0).length)
const totalNeed=computed(()=>list.value.reduce((sum,item)=>sum+item.needNum,0)),totalDone=computed(()=>list.value.reduce((sum,item)=>sum+item.submittedNum,0))
const selectedItems=computed(()=>visibleList.value.filter(item=>selected.value.includes(item.key))),selectedUnits=computed(()=>selectedItems.value.reduce((sum,item)=>sum+item.pendingNum,0)),allSelected=computed(()=>visibleList.value.length>0&&visibleList.value.every(item=>selected.value.includes(item.key)))
const rankText=(rank:number)=>['','A级','B级','C级','D级','E级'][rank]||`${rank}级`
async function load(){loading.value=true;error.value='';try{list.value=await restockApi.demand(date.value,{zone:zone.value,type:type.value});selected.value=[]}catch(e){error.value=e instanceof Error?e.message:'补货数据加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
async function loadZones(){zones.value=await distributionApi.filterOptions(date.value)}
async function changeSession(){zone.value='';await loadZones();await load()}
function chooseType(value:number){type.value=value;load()}
function openZone(){draftZone.value=zone.value;zoneVisible.value=true}
function confirmZone(){zone.value=draftZone.value;zoneVisible.value=false;load()}
function toggle(item:RestockDemand){if(status.value!=='pending'||!item.pendingNum)return;selected.value=selected.value.includes(item.key)?selected.value.filter(key=>key!==item.key):[...selected.value,item.key]}
function toggleAll(){selected.value=allSelected.value?[]:visibleList.value.map(item=>item.key)}
function openSubmit(){if(!selectedItems.value.length)return uni.showToast({title:'请先选择补货数据',icon:'none'});const ids=[...new Set(selectedItems.value.flatMap(item=>item.enterItemIds))];uni.setStorageSync('restockSubmitItems',ids);uni.navigateTo({url:`/features/restock/pages/submit/index?date=${date.value}`})}
function openHistory(){uni.navigateTo({url:`/features/restock/pages/history/index?date=${date.value}`})}
onLoad(query=>{if(query?.date)date.value=String(query.date);loadZones();load()});onShow(load);onPullDownRefresh(load)
</script>

<template><view class="page">
  <view class="page-head"><SessionTrigger :value="date" @click="sessionPickerVisible=true"/><view class="head-badge">补货管理</view></view>
  <view class="hero"><view><text>本场次补货进度</text><strong>{{totalDone}}<small>/{{totalNeed}} 扎</small></strong></view><view class="ring">{{totalNeed?Math.round(totalDone/totalNeed*100):0}}%</view></view>
  <view class="toolbar"><view class="search"><input v-model="keyword" placeholder="搜索花材名称"/></view><view class="zone-trigger" @click="openZone">{{zone?(zones.find(item=>item.zone===zone)?.areaName||`${Number(zone)}区`):'全部分区'}}<text class="down"/></view></view>
  <view class="type-row"><view :class="{active:type===0}" @click="chooseType(0)">全部类型</view><view :class="{active:type===1}" @click="chooseType(1)">缺货补货</view><view :class="{active:type===2}" @click="chooseType(2)">退货补货</view></view>
  <view class="history-entry" @click="openHistory"><view><strong>历史补货单</strong><text>查看补货计划与出库进度</text></view><text class="history-arrow"/></view>
  <view class="tabs"><view :class="{active:status==='pending'}" @click="status='pending'">补货需求 {{pendingKinds}}</view><view :class="{active:status==='completed'}" @click="status='completed'">已完成 {{completedKinds}}</view><text>按花材汇总</text></view>
  <view v-if="status==='pending'&&visibleList.length" class="select-head" @click="toggleAll"><view :class="['check',{checked:allSelected}]">{{allSelected?'✓':''}}</view><text>{{allSelected?'取消全选':'全选当前结果'}}</text><small>按剩余需求选择</small></view>
  <WareState v-if="loading" type="loading" title="正在加载补货任务"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/>
  <view v-else-if="visibleList.length" class="cards"><view v-for="item in visibleList" :key="item.key" :class="['card',{selected:selected.includes(item.key)}]" @click="expanded=expanded===item.key?'':item.key"><view class="card-main"><view v-if="status==='pending'" :class="['check',{checked:selected.includes(item.key)}]" @click.stop="toggle(item)">{{selected.includes(item.key)?'✓':''}}</view><view class="flower"><strong>{{item.productName}}<text>{{rankText(item.rank)}}</text></strong><small>{{item.skuConfig||'暂无规格信息'}}</small></view><view class="progress-num"><strong>{{item.pendingNum}}扎</strong><small>{{item.submittedNum?`已补 ${item.submittedNum}/${item.needNum}`:'剩余需补'}}</small></view><text class="arrow" :class="{open:expanded===item.key}"/></view><view class="bar"><view :style="{width:(item.needNum?item.submittedNum/item.needNum*100:0)+'%'}"/></view><view v-if="expanded===item.key" class="detail"><view><text>补货分区</text><strong>{{zones.find(entry=>entry.zone===item.zone)?.areaName||`${Number(item.zone)}区`}}</strong></view><view><text>缺货补货</text><strong>{{item.shortageNeed}}扎</strong></view><view><text>退货补货</text><strong>{{item.returnNeed}}扎</strong></view><view><text>场地补货</text><strong>{{item.siteNeed}}扎</strong></view></view></view></view>
  <WareState v-else type="empty" title="暂无补货任务" description="当前场次和筛选条件下没有对应的补货需求"/>
  <view v-if="status==='pending'" class="submit-bar"><view><strong>已选 {{selectedItems.length}} 类</strong><text>涉及 {{selectedUnits}} 扎剩余需求</text></view><button :disabled="!selectedItems.length" @click="openSubmit">我要补货</button></view>
  <view v-if="zoneVisible" class="mask" @click="zoneVisible=false"><view class="drawer" @click.stop><view class="drawer-head"><strong>选择分区</strong><text @click="confirmZone">确定</text></view><scroll-view scroll-y class="zone-scroll"><view class="zone-grid"><view :class="{active:!draftZone}" @click="draftZone=''">全部分区</view><view v-for="item in zones" :key="item.zone" :class="{active:draftZone===item.zone}" @click="draftZone=item.zone">{{item.areaName||`${Number(item.zone)}区`}}</view></view></scroll-view></view></view>
  <SessionDatePicker v-model="date" v-model:visible="sessionPickerVisible" @confirm="changeSession"/>
</view></template>

