ground:var(--wms-surface-soft);color:var(--wms-primary-700)}
.page{padding-bottom:170rpx}.select-head{display:flex;height:62rpx;align-items:center;gap:10rpx;color:var(--wms-primary-700);font-size:20rpx}.select-head small{margin-left:auto;color:var(--wms-text-secondary);font-size:19rpx}.check{display:flex;width:27rpx;height:27rpx;align-items:center;justify-content:center;border:2rpx solid #aebbb8;border-radius:6rpx;color:#fff;font-size:17rpx}.check.checked{border-color:var(--wms-primary-700);background:var(--wms-primary-700)}.card.selected{box-shadow:inset 0 0 0 2rpx var(--wms-primary-700),var(--wms-shadow-card)}.card-main{grid-template-columns:34rpx minmax(0,1fr) 120rpx 24rpx}.card-main>.flower{grid-column:1/3}.card-main>.check+.flower{grid-column:2}.card-main>.progress-num{grid-column:3}.card-main>.arrow{grid-column:4}.submit-bar{position:fixed;right:0;bottom:0;left:0;z-index:12;display:flex;align-items:center;justify-content:space-between;padding:14rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));border-top:1rpx solid var(--wms-border);background:#fff}.submit-bar strong,.submit-bar text{display:block}.submit-bar strong{font-size:22rpx}.submit-bar text{margin-top:4rpx;color:var(--wms-text-secondary);font-size:18rpx}.submit-bar button{width:230rpx;height:70rpx;margin:0;border:0;border-radius:14rpx;background:var(--wms-primary-700);color:#fff;font-size:23rpx;line-height:70rpx}.submit-bar button[disabled]{background:#cbd7d4;color:#fff}.confirm-head{display:grid;grid-template-columns:100rpx 1fr 100rpx;align-items:center}.confirm-head strong{text-align:center}.confirm-head text{color:var(--wms-text-secondary);font-size:22rpx}.confirm-head text:last-child{color:var(--wms-primary-700);text-align:right}.confirm-summary{display:grid;grid-template-columns:repeat(3,1fr);margin-top:28rpx;padding:23rpx 0;border-radius:17rpx;background:var(--wms-surface-soft)}.confirm-summary view{display:flex;align-items:center;flex-direction:column;border-right:1rpx solid var(--wms-border)}.confirm-summary view:last-child{border:0}.confirm-summary te